// Builds a demo catalogue: 10 pieces in each of the five categories, all
// pointing at the one sample photo in public/. Run: npm run demo:sql
//
// The data is deliberately spread across stones, metals, price bands, ring
// sizes and sold status, so every filter on /jewelry has something to find and
// something to exclude. This is test data — delete it before the shop opens
// (the last statement in the generated file removes exactly these rows).

import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

/** Served by the site itself, so no Storage upload is needed to see it work. */
const PHOTO = "/test-photo.jpg";

const STONES = [
  { key: "sapphire", th: "ไพลิน", colour: "น้ำเงิน" },
  { key: "ruby", th: "ทับทิม", colour: "แดง" },
  { key: "emerald", th: "มรกต", colour: "เขียว" },
  { key: "diamond", th: "เพชร", colour: "น้ำขาว D–F" },
  { key: "star", th: "พลอยสตาร์", colour: "เทาเงิน" },
];

const METALS = ["ทอง 90", "ทอง 18K", "ทองคำขาว 18K"];

const CATEGORIES = [
  {
    key: "ring",
    prefix: "RG",
    names: ["แหวนล้อมเพชร", "แหวนบ่าเพชร", "แหวนเรือนคลาสสิก", "แหวนหัวชู", "แหวนแถวเรียง"],
    settings: ["ล้อมเพชรรอบเม็ดกลาง", "บ่าฝังเพชรสองข้าง", "หนามเตยหกจุด", "ฝังหุ้มขอบเรียบ"],
  },
  {
    key: "earring",
    prefix: "ER",
    names: ["ต่างหูหยดน้ำ", "ต่างหูระย้า", "ต่างหูติดหู", "ต่างหูห่วงล้อมเพชร", "ต่างหูดอกไม้"],
    settings: ["เม็ดกลางล้อมเพชรเล็ก", "ห้อยระย้าสองชั้น", "ฝังเรียงไล่ขนาด", "หนามเตยสี่จุด"],
  },
  {
    key: "bracelet",
    prefix: "BR",
    names: ["สร้อยข้อมือเทนนิส", "สร้อยข้อมือเรือนทอง", "กำไลฝังพลอย", "สร้อยข้อมือดอกไม้", "กำไลเรียบ"],
    settings: ["เรียงรอบวงเท่ากันทุกเม็ด", "สลับเพชรกับพลอย", "ฝังกลุ่มดอกไม้", "เม็ดเดี่ยวกลางเรือน"],
  },
  {
    key: "brooch",
    prefix: "BC",
    names: ["เข็มกลัดดอกไม้", "เข็มกลัดโบว์", "เข็มกลัดนกยูง", "เข็มกลัดใบไม้", "เข็มกลัดผีเสื้อ"],
    settings: ["ฝังไล่เฉดจากกลางออก", "เม็ดกลางล้อมเพชร", "ฝังกระจายทั้งตัว", "ตาฝังพลอยเม็ดเล็ก"],
  },
  {
    key: "pendant",
    prefix: "PD",
    names: ["จี้เม็ดเดี่ยว", "จี้หยดน้ำ", "จี้หัวใจ", "จี้ล้อมเพชร", "จี้ดาว"],
    settings: ["เม็ดเดี่ยวหนามเตย", "ล้อมเพชรสองชั้น", "ฝังหุ้มขอบ", "ห้อยเม็ดกลางอิสระ"],
  },
];

/** Spread across the three price bands the catalogue filters by. */
const PRICES = [
  28_500, 36_900, 42_000, 47_800, 58_000, 64_500, 72_000, 89_000, 118_000, 145_000,
];

const RING_SIZES = [48, 50, 51, 52, 54, 55, 56, 57, 58, 60];

const q = (v) =>
  v === null || v === undefined ? "null" : `'${String(v).replace(/'/g, "''")}'`;

const rows = [];
let serial = 200;

for (const category of CATEGORIES) {
  for (let i = 0; i < 10; i += 1) {
    serial += 1;
    const stone = STONES[i % STONES.length];
    const metal = METALS[i % METALS.length];
    const isRing = category.key === "ring";
    // Two sold pieces per category, so /portfolio and the sold filter fill up.
    const sold = i === 3 || i === 7;

    rows.push({
      sku: `${category.prefix}${serial}`,
      name: `${category.names[i % category.names.length]}${stone.th}`,
      category: category.key,
      metal_type: metal,
      gold_weight_g: (3 + ((i * 7) % 60) / 10).toFixed(2),
      stone_type: stone.key,
      stone_carat: stone.key === "diamond" ? (0.3 + i * 0.12).toFixed(2) : null,
      stone_carat_note: category.settings[i % category.settings.length],
      stone_color: stone.colour,
      cert_lab: stone.key === "diamond" ? "GIA" : null,
      ring_size_th: isRing ? RING_SIZES[i] : null,
      price: PRICES[i],
      description:
        "ชิ้นตัวอย่างสำหรับทดสอบระบบ ยังไม่ใช่สินค้าจริงของร้าน",
      sold,
    });
  }
}

const values = rows
  .map(
    (r) =>
      `  (${q(r.sku)}, ${q(r.name)}, ${q(r.category)}, ${q(r.metal_type)}, ${r.gold_weight_g}, ` +
      `${q(r.stone_type)}, ${r.stone_carat ?? "null"}, ${q(r.stone_carat_note)}, ${q(r.stone_color)}, ` +
      `${q(r.cert_lab)}, ${r.ring_size_th ?? "null"}, ${r.price}, ${q(r.description)}, ` +
      `'published', ${r.sold ? "now()" : "null"}, now())`,
  )
  .join(",\n");

const sql = `-- demo-catalogue.sql — GENERATED by scripts/generate-demo-catalogue.mjs
--
-- ${rows.length} test pieces, 10 per category, all sharing the sample photo at
-- public/test-photo.jpg. Spread across stones, metals, price bands and ring
-- sizes so every filter on /jewelry has something to match and something to
-- exclude. Two pieces per category are marked sold.
--
-- THIS IS TEST DATA. The last statement in this file removes exactly these
-- rows and nothing else — run it before the shop goes live.

begin;

insert into products (
  sku, name, category, metal_type, gold_weight_g,
  stone_type, stone_carat, stone_carat_note, stone_color,
  cert_lab, ring_size_th, price, description,
  status, sold_at, published_at
) values
${values}
on conflict (sku) do nothing;

-- One photo row per piece. A storage_path beginning with "/" is a file the
-- site serves itself, so this needs no upload into Supabase Storage.
insert into product_images (product_id, storage_path, alt_th, sort_order)
select p.id, ${q(PHOTO)}, p.name || ' ' || p.sku, 0
from products p
where p.description = 'ชิ้นตัวอย่างสำหรับทดสอบระบบ ยังไม่ใช่สินค้าจริงของร้าน'
  and not exists (select 1 from product_images pi where pi.product_id = p.id);

commit;

-- ---------------------------------------------------------------------------
-- ลบข้อมูลตัวอย่างทั้งหมด (รันเมื่อจะเอาของจริงขึ้น)
-- delete from products
--  where description = 'ชิ้นตัวอย่างสำหรับทดสอบระบบ ยังไม่ใช่สินค้าจริงของร้าน';
-- ---------------------------------------------------------------------------
`;

writeFileSync(join(root, "supabase/demo-catalogue.sql"), sql, "utf8");
console.log(`demo-catalogue.sql written: ${rows.length} products`);
